using System;
using System.Diagnostics;
using System.Drawing;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Reflection;
using System.Threading.Tasks;
using System.Windows.Forms;

class Setup : Form {
 static bool Patch {get{return Assembly.GetExecutingAssembly().GetManifestResourceNames().Contains("patch.flag");}}
 TextBox folder=new TextBox {Dock=DockStyle.Fill};Label status=new Label {Dock=DockStyle.Fill,AutoSize=false};ProgressBar progress=new ProgressBar {Dock=DockStyle.Bottom,Height=24};Button install=new Button {Text="Installieren / Aktualisieren",AutoSize=true,Padding=new Padding(12)};CheckBox shortcut=new CheckBox {Text="Verknüpfung auf dem Desktop anlegen",Checked=true,AutoSize=true};bool busy;
 public Setup(string selectedTarget){Text="SpielfeldTV "+(Patch?"Update":"Setup")+" · Installer 0.8.0";Font=new Font("Segoe UI",10);Size=new Size(820,520);MinimumSize=Size;StartPosition=FormStartPosition.CenterScreen;
  var panel=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(24),ColumnCount=2,RowCount=6};panel.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));panel.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,120));
  var title=new Label {Text="SpielfeldTV installieren oder aktualisieren",AutoSize=true,Font=new Font("Segoe UI",17,FontStyle.Bold)};panel.Controls.Add(title,0,0);panel.SetColumnSpan(title,2);
  var info=new Label {Text="Kein ZIP-Entpacken nötig. Kameraeinstellungen bleiben erhalten.\nBitte die laufende SpielfeldTV-Anwendung vor dem Update schließen.",AutoSize=true,Padding=new Padding(0,14,0,14)};panel.Controls.Add(info,0,1);panel.SetColumnSpan(info,2);
  folder.Text=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Programs","SpielfeldTV");if(!String.IsNullOrEmpty(selectedTarget))folder.Text=selectedTarget;panel.Controls.Add(folder,0,2);var browse=new Button{Text="Ordner wählen",AutoSize=true};browse.Click+=(s,e)=>{using(var dlg=new FolderBrowserDialog()){dlg.SelectedPath=folder.Text;if(dlg.ShowDialog(this)==DialogResult.OK)folder.Text=dlg.SelectedPath;}};panel.Controls.Add(browse,1,2);
  panel.Controls.Add(shortcut,0,3);panel.SetColumnSpan(shortcut,2);panel.Controls.Add(status,0,4);panel.SetColumnSpan(status,2);status.Text=Patch?"Kleines Update für eine vorhandene SpielfeldTV-Installation. VLC wird beibehalten.":"Das Komplett-Setup enthält VLC. Kein separates VLC-Setup erforderlich.";panel.RowStyles.Add(new RowStyle(SizeType.AutoSize));panel.RowStyles.Add(new RowStyle(SizeType.AutoSize));panel.RowStyles.Add(new RowStyle(SizeType.AutoSize));panel.RowStyles.Add(new RowStyle(SizeType.AutoSize));panel.RowStyles.Add(new RowStyle(SizeType.Percent,100));panel.RowStyles.Add(new RowStyle(SizeType.AutoSize));panel.Controls.Add(install,0,5);Controls.Add(panel);Controls.Add(progress);
  install.Click+=async(s,e)=>{if(busy)return;try{if(RelaunchFromTarget(folder.Text)){Close();return;}}catch(Exception ex){status.Text=ex.Message;return;}busy=true;folder.Enabled=browse.Enabled=install.Enabled=false;try {string target=Path.GetFullPath(folder.Text.Trim());status.Text="Programmdateien werden vorbereitet …";await Task.Run(()=>Extract(target,new ProgressProxy(n=>{if(!IsDisposed)BeginInvoke((Action)(()=>progress.Value=Math.Min(100,n)));})));if(shortcut.Checked)Shortcut(target);status.Text="Installation erfolgreich. SpielfeldTV wird geöffnet.";Process.Start(Path.Combine(target,"SpielfeldTV.exe"));busy=false;Close();}catch(Exception ex){status.Text=ex.Message;}finally{busy=false;if(!IsDisposed)folder.Enabled=browse.Enabled=install.Enabled=true;}};
  FormClosing+=(s,e)=>{if(busy){e.Cancel=true;status.Text="Installation wird abgeschlossen. Bitte kurz warten.";}};
 }
 class ProgressProxy : IProgress<int>{Action<int> report;public ProgressProxy(Action<int> action){report=action;}public void Report(int n){report(n);}}
 static void StopLegacyHelper(string target){string expected=Path.GetFullPath(Path.Combine(target,"bridge","go2rtc.exe"));foreach(var helper in Process.GetProcessesByName("go2rtc")){using(helper){string path;try{path=helper.MainModule.FileName;}catch{continue;}if(!String.Equals(Path.GetFullPath(path),expected,StringComparison.OrdinalIgnoreCase))continue;try{helper.Kill();if(!helper.WaitForExit(4000))throw new Exception("timeout");}catch{throw new Exception("Der alte SpielfeldTV-Kamerahilfsprozess konnte nicht beendet werden. Bitte SpielfeldTV vollständig schließen und erneut versuchen.");}}}}
 static void SafeDeleteStage(string path,string parent){string full=Path.GetFullPath(path),prefix=Path.GetFullPath(parent).TrimEnd(Path.DirectorySeparatorChar)+Path.DirectorySeparatorChar;if(!full.StartsWith(prefix,StringComparison.OrdinalIgnoreCase)||!Path.GetFileName(full).StartsWith(".SpielfeldTV-stage-",StringComparison.Ordinal))throw new Exception("Temporärer Pfad ist ungültig.");if(Directory.Exists(full))Directory.Delete(full,true);}
 public static void Extract(string target,IProgress<int> report){
  target=Path.GetFullPath(target);Directory.SetCurrentDirectory(Path.GetTempPath());
  string key;using(var sha=System.Security.Cryptography.SHA256.Create())key=BitConverter.ToString(sha.ComputeHash(System.Text.Encoding.UTF8.GetBytes(Path.GetFullPath(target).ToLowerInvariant()))).Replace("-","");
  using(var mutex=new System.Threading.Mutex(false,"Local\\SpielfeldTV-Install-"+key)){bool entered;try{entered=mutex.WaitOne(0);}catch(System.Threading.AbandonedMutexException){entered=true;}if(!entered)throw new Exception("Für diesen Ordner läuft bereits ein Update. Bitte das andere Update-Fenster zuerst abschließen.");try{ExtractCore(target,report);}finally{mutex.ReleaseMutex();}}
 }
 static void ExtractCore(string target,IProgress<int> report){
  target=Path.GetFullPath(target).TrimEnd(Path.DirectorySeparatorChar);string parent=Path.GetDirectoryName(target);if(String.IsNullOrEmpty(parent)||Path.GetPathRoot(target).TrimEnd('\\')==target)throw new Exception("Bitte einen eigenen Programm-Unterordner wählen.");
  if(File.Exists(target))throw new Exception("Der Zielpfad ist eine Datei. Bitte einen Ordner wählen.");
  if(Patch&&!File.Exists(Path.Combine(target,"vlc","libvlc.dll")))throw new Exception("Bitte den Ordner der vorhandenen SpielfeldTV-Installation wählen. Ohne vorherige Installation zuerst das Komplett-Setup verwenden.");
  if(Directory.Exists(target)&&Directory.EnumerateFileSystemEntries(target).Any()&&!File.Exists(Path.Combine(target,"SpielfeldTV.exe")))throw new Exception("Der Ordner enthält andere Dateien. Bitte einen leeren Ordner oder die vorhandene SpielfeldTV-Installation wählen.");
  foreach(var process in Process.GetProcessesByName("SpielfeldTV")){process.Dispose();throw new Exception("Bitte SpielfeldTV schließen und erneut auf Installieren / Aktualisieren klicken.");}
  StopLegacyHelper(target);
  Directory.CreateDirectory(parent);string stage=Path.Combine(parent,".SpielfeldTV-stage-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(stage);string backup=target+".vorher-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+"-"+Guid.NewGuid().ToString("N").Substring(0,6);bool moved=false;string operation="Programmdateien vorbereiten";
  try {if(Patch){foreach(var source in Directory.EnumerateFiles(target,"*",SearchOption.AllDirectories)){string relative=source.Substring(target.Length+1);string destination=Path.Combine(stage,relative);Directory.CreateDirectory(Path.GetDirectoryName(destination));operation="Vorhandene Datei kopieren: "+relative;File.Copy(source,destination,true);}}
   using(var payload=Assembly.GetExecutingAssembly().GetManifestResourceStream("payload.zip")){if(payload==null)throw new Exception("Installationsdaten fehlen.");using(var zip=new ZipArchive(payload,ZipArchiveMode.Read)){
    int done=0;foreach(var entry in zip.Entries){string name=entry.FullName.Replace('\\','/');if(name=="SpielfeldTV/"||name=="SpielfeldTV")continue;if(!name.StartsWith("SpielfeldTV/",StringComparison.Ordinal))throw new Exception("Ungültiges Installationspaket.");string relative=name.Substring("SpielfeldTV/".Length);string file=Path.GetFullPath(Path.Combine(stage,relative.Replace('/',Path.DirectorySeparatorChar)));if(!file.StartsWith(stage+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new Exception("Ungültiger Archivpfad.");if(name.EndsWith("/")){Directory.CreateDirectory(file);continue;}Directory.CreateDirectory(Path.GetDirectoryName(file));using(var source=entry.Open())using(var output=File.Create(file))source.CopyTo(output);report.Report(++done*90/Math.Max(1,zip.Entries.Count));}
   }}
   if(!File.Exists(Path.Combine(stage,"SpielfeldTV.exe"))||!File.Exists(Path.Combine(stage,"vlc","libvlc.dll")))throw new Exception("Das Paket ist unvollständig. Kamera-Laufzeit oder Programmdateien fehlen.");
   operation="Bisherigen Programmordner sichern";if(Directory.Exists(target)){MoveWithRetry(target,backup);moved=true;}operation="Neue Programmversion einsetzen";try{MoveWithRetry(stage,target);}catch{if(moved&&!Directory.Exists(target))Directory.Move(backup,target);throw;}report.Report(100);
  }catch(IOException ex){int code=ex.HResult&65535;string reason=(code==32||code==33)?"Eine Datei oder der Programmordner ist noch durch einen anderen Prozess gesperrt.":"Dateifehler beim Installieren.";throw new IOException(reason+"\nSchritt: "+operation+"\nWindows-Fehler "+code+": "+ex.Message+"\nBitte das Update aus Downloads starten. Falls die Sperre bleibt: Windows neu starten und vor SpielfeldTV das Update ausführen.",ex);}finally{try{SafeDeleteStage(stage,parent);}catch(IOException){}catch(UnauthorizedAccessException){}}
 }
 static void Shortcut(string target){Type t=Type.GetTypeFromProgID("WScript.Shell");if(t==null)return;object shell=Activator.CreateInstance(t);string desktop=Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory);object link=t.InvokeMember("CreateShortcut",BindingFlags.InvokeMethod,null,shell,new object[]{Path.Combine(desktop,"SpielfeldTV.lnk")});Type lt=link.GetType();lt.InvokeMember("TargetPath",BindingFlags.SetProperty,null,link,new object[]{Path.Combine(target,"SpielfeldTV.exe")});lt.InvokeMember("WorkingDirectory",BindingFlags.SetProperty,null,link,new object[]{target});lt.InvokeMember("Save",BindingFlags.InvokeMethod,null,link,null);}
 static void MoveWithRetry(string source,string destination){for(int attempt=0;;attempt++){try{Directory.Move(source,destination);return;}catch(IOException ex){int code=ex.HResult&65535;if(attempt>=5||(code!=32&&code!=33))throw;System.Threading.Thread.Sleep(400);}}}
 static bool IsInside(string file,string folder){string root=Path.GetFullPath(folder).TrimEnd(Path.DirectorySeparatorChar);string value=Path.GetFullPath(file);return value.StartsWith(root+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase);}
 static bool RelaunchFromTarget(string target){target=Path.GetFullPath(target);string self=Assembly.GetExecutingAssembly().Location;if(!IsInside(self,target))return false;string temp=Path.Combine(Path.GetTempPath(),"SpielfeldTV-Installer-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(temp);string copy=Path.Combine(temp,Path.GetFileName(self));File.Copy(self,copy);Process.Start(new ProcessStartInfo(copy){UseShellExecute=true,WorkingDirectory=temp,Arguments="--target \""+target+"\" --wait-pid "+Process.GetCurrentProcess().Id});return true;}
 [STAThread] static int Main(string[] args){string selectedTarget=null;int waitPid=0;for(int i=0;i<args.Length-1;i++){if(args[i]=="--target")selectedTarget=Path.GetFullPath(args[++i]);else if(args[i]=="--wait-pid")Int32.TryParse(args[++i],out waitPid);}Directory.SetCurrentDirectory(Path.GetTempPath());if(waitPid>0)try{using(var p=Process.GetProcessById(waitPid)){if(!p.WaitForExit(30000)){MessageBox.Show("Der vorige Programmprozess beendet sich nicht. Bitte Windows neu starten und das Update erneut ausführen.","SpielfeldTV Update");return 1;}}}catch(ArgumentException){}
 if(args.Length==2&&args[0]=="--test-install"){try{Extract(args[1],new ProgressProxy(n=>{}));Console.WriteLine("PASS: self-extracting setup installation.");return 0;}catch(Exception ex){Console.Error.WriteLine(ex);return 1;}}
 Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);Application.Run(new Setup(selectedTarget));return 0;}
}

